Make `load()` async and let the caller own the task. With **Default Actor Isolation = MainActor**, the model needs no explicit `@MainActor`, and there’s no need to dispatch UI updates back to the main queue.

```swift
import Foundation
import Observation

@Observable
final class FeedModel {
    private(set) var items: [Item] = []
    private(set) var isLoading = false
    private(set) var loadError: (any Error)?

    private let feedURL: URL

    init(feedURL: URL) {
        self.feedURL = feedURL
    }

    func load() async {
        guard !isLoading, !Task.isCancelled else { return }

        isLoading = true
        loadError = nil
        defer { isLoading = false }

        do {
            let (data, response) = try await URLSession.shared.data(from: feedURL)

            if let http = response as? HTTPURLResponse,
               !(200..<300).contains(http.statusCode) {
                throw FeedLoadError.httpStatus(http.statusCode)
            }

            try Task.checkCancellation()
            items = Parser.parse(data)
        } catch is CancellationError {
            // Cancellation isn't a load failure.
        } catch {
            // URLSession can also report cancellation as a URL error.
            guard !Task.isCancelled else { return }
            loadError = error
        }
    }

    private enum FeedLoadError: Error {
        case httpStatus(Int)
    }
}
```

